const panel=document.querySelector('#panel');let current=0,platform='android',done=[];try{const saved=JSON.parse(localStorage.getItem('delta-guide-progress')||'[]');if(Array.isArray(saved))done=saved.filter(x=>[0,1,2].includes(x));}catch{}
const shot=(n,alt)=>`<button class="screenshot" data-image="assets/image${n}.png" aria-label="放大${alt}"><img src="assets/image${n}.png" alt="${alt}"><span>点击看大图 ↗</span></button>`;
const bottom=()=>`<div class="panel-bottom"><span>${done.includes(current)?'✓ 这一步已标记完成':'完成实际操作后，再继续下一步'}</span><button class="primary" id="complete">${current===2?'我已完成设置':'已完成，下一步'} <span>→</span></button></div>`;
function render(){document.querySelectorAll('.step').forEach((b,i)=>{b.classList.toggle('active',i===current);b.classList.toggle('done',done.includes(i));if(i===current)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');b.querySelector('.step-number').textContent=done.includes(i)?'✓':`0${i+1}`});document.querySelector('#progress-text').textContent=`${done.length} / 3`;document.querySelector('#progress').style.width=`${done.length/3*100}%`;
if(current===0){panel.innerHTML=`<div class="panel-heading"><h3>先安装 Delta Chat</h3><span class="badge">STEP 01 / 03</span></div><p class="description">选择你使用的手机，找到对应的下载方式。</p><div class="tabs" role="tablist" aria-label="手机类型"><button role="tab" aria-selected="${platform==='android'}" class="tab ${platform==='android'?'selected':''}" data-platform="android">Android 安卓</button><button role="tab" aria-selected="${platform==='ios'}" class="tab ${platform==='ios'?'selected':''}" data-platform="ios">iPhone 苹果</button></div><div role="tabpanel">${platform==='android'?`<h4>下载 Android 安装包</h4><p>点击下方按钮下载安装包，下载完成后打开并安装。</p><a class="secondary" target="_blank" rel="noopener noreferrer" href="https://mouss.synology.me:1050/delta.apk">下载 Android 安装包 ↓</a><a class="helper-link" href="https://delta.chat/en/download" target="_blank" rel="noopener noreferrer">其他官方下载方式 ↗</a><div class="tip">安装包由指南提供者维护。安装完成后，返回这里继续创建账号。</div>`:`<div class="content-row"><div><h4>在 App Store 搜索 Delta Chat</h4><p>原文使用香港或海外地区的 App Store。若搜索不到，请向指南提供者询问安装方式。</p><a class="secondary" target="_blank" rel="noopener noreferrer" href="https://delta.chat/en/download">查看官方下载选项 ↗</a></div>${shot(1,'App Store 搜索截图')}</div><div class="tip">原文的 iOS 分版本教程未附链接。使用自己的账号；如曾切换 App Store 账号，安装后切回原账号。</div>`}</div>${bottom()}`}
if(current===1){panel.innerHTML=`<div class="panel-heading"><h3>创建你的聊天账号</h3><span class="badge">STEP 02 / 03</span></div><p class="description">先完成安装，再用手机打开配置入口。</p><div class="content-row"><div><a class="secondary" href="https://talk.cmsv.space/" target="_blank" rel="noopener noreferrer">打开账号配置页面 ↗</a><ol class="numbered"><li>点击网页中的“在 Delta Chat 中创建账号”。</li><li>跳转到应用后，核对服务器地址。</li><li>填写你的名字，点击“同意并创建账号”。</li></ol></div>${shot(3,'账号创建界面')}</div><div class="copy-row"><code>talk.cmsv.space</code><button data-copy="talk.cmsv.space">复制地址</button></div><div class="tip">请确认地址与上方一致。入口来自原文；如无法访问，请联系指南提供者。</div>${bottom()}`}
if(current===2){panel.innerHTML=`<div class="panel-heading"><h3>找到好友，开始聊天</h3><span class="badge">STEP 03 / 03</span></div><p class="description">通过好友助手加入联系网络，再查找你认识的人。</p><div class="missing">先向指南提供者索取“好友助手”邀请链接。原文没有附上可用链接，获取后用 Delta Chat 打开并确认添加。</div><ol class="numbered"><li>向好友助手发送下方口令，加入联系网络。</li><li>按提示输入你的名字，建议两个字或三个字。</li><li>发送“查找好友”，再输入对方的名字。</li><li>按搜索结果回复数字，选择正确的联系人。</li><li>等待对方点击名片添加，即可开始聊天。</li></ol><div class="copy-row"><code>xhsybyx</code><button data-copy="xhsybyx">复制入网口令</button></div><div class="copy-row"><code>查找好友</code><button data-copy="查找好友">复制查找指令</button></div>${bottom()}`}
}
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
document.addEventListener('click',async e=>{const step=e.target.closest('[data-step]');if(step){current=Number(step.dataset.step);render();return}const tab=e.target.closest('[data-platform]');if(tab){platform=tab.dataset.platform;render();panel.querySelector(`[data-platform="${platform}"]`).focus();return}const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);toast('已复制，可粘贴到 Delta Chat')}catch{toast('复制未成功，请手动选择并复制文字')}return}const img=e.target.closest('[data-image]');if(img){document.querySelector('#large-image').src=img.dataset.image;document.querySelector('#image-dialog').showModal();return}if(e.target.closest('#complete')){if(!done.includes(current))done.push(current);try{localStorage.setItem('delta-guide-progress',JSON.stringify(done))}catch{}if(current<2)current++;else toast('设置已完成，去和好友打个招呼吧！');render();panel.focus();}if(e.target.closest('#reset')){done=[];current=0;try{localStorage.removeItem('delta-guide-progress')}catch{}render();toast('进度已重置')}if(e.target.closest('#close-image'))document.querySelector('#image-dialog').close()});
document.querySelector('#image-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});render();
